package com.hs.jxc.it;

import static org.assertj.core.api.Assertions.*;
import com.hs.jxc.common.api.JsonCodec;
import com.hs.jxc.inv.api.InventoryApi;
import com.hs.jxc.cst.service.CostValuationService;
import java.math.*;
import java.net.URI;
import java.net.http.*;
import java.time.LocalDate;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.web.server.LocalServerPort;

/** Real PostgreSQL economics and current authorization, using the shared supply fixture. */
class ProfitIT extends SupplyFixtures {
 @Autowired InventoryApi inventory; @Autowired CostValuationService valuation; @Autowired JsonCodec json;
 @Autowired com.hs.jxc.rtn.ReturnsService returns; @Autowired com.hs.jxc.workflow.service.WorkflowService workflow;
 @LocalServerPort int port;
 @BeforeEach void profitSetup(){seed("UPDATE sys_role SET field_policies=field_policies||'{\"PROFIT\":\"READ\"}'::jsonb WHERE id=202");seed("INSERT INTO md_customer(id,country_id,code,name) VALUES(1101,101,'C','Customer')");seed("INSERT INTO fin_period(id,country_id,book_id,fiscal_year,period_no,start_date,end_date,status) VALUES(702,101,601,2026,11,'2026-11-01','2026-11-30','OPEN')");}
 Map<String,Object> http(String path,Map<String,Object> body){try{var b=HttpRequest.newBuilder(URI.create("http://localhost:"+port+"/api/v1/"+path)).header("Authorization","Bearer supply-fixture").header("X-Country-Id","101");if(body==null)b.GET();else b.header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(json.write(body)));var r=HttpClient.newHttpClient().send(b.build(),HttpResponse.BodyHandlers.ofString());var result=json.readMap(r.body());result.put("httpStatus",r.statusCode());return result;}catch(Exception e){throw new RuntimeException(e);}}
 @SuppressWarnings("unchecked") Map<String,Object> profit(String params){var r=http("cst/profit?bookId=601&"+params,null);assertThat(r.get("httpStatus")).as(r.toString()).isEqualTo(200);return (Map<String,Object>)r.get("data");}
 @SuppressWarnings("unchecked") Map<String,Object> product(Map<String,Object> result,long product){return ((List<Map<String,Object>>)result.get("rows")).stream().filter(r->((Number)r.get("productId")).longValue()==product).findFirst().orElseThrow();}
 void amount(Map<String,Object> r,String field,String expected){assertThat(new BigDecimal(r.get(field).toString())).as(field).isEqualByComparingTo(expected);}
 long stock(String ccy,String price){return inCountry(101,()->inventory.inbound(c(),new InventoryApi.Inbound(601,401,501,new BigDecimal("10"),BigDecimal.ZERO,BigDecimal.ZERO,new InventoryApi.Source("TEST_IN",9001,9001,"IN"),LocalDate.of(2026,10,15),null,null,new InventoryApi.PurchaseCost(9001,9001,ccy,new BigDecimal(price),new BigDecimal(price).multiply(BigDecimal.TEN),BigDecimal.TEN)))).id();}
 void sale(String ccy){sale(ccy,"0");} void sale(String ccy,String taxRate){new org.springframework.transaction.support.TransactionTemplate(new org.springframework.jdbc.datasource.DataSourceTransactionManager(owner.getDataSource())).executeWithoutResult(s->{seed("INSERT INTO sal_order(id,country_id,book_id,entity_id,customer_id,doc_no,order_date,currency,payment_type,entered_by,total_qty,total_amount) VALUES(1201,101,601,301,1101,'SO','2026-10-15',?,'CREDIT',201,4,79.9999)",ccy);seed("INSERT INTO sal_order_line(id,country_id,book_id,order_id,product_id,line_no,unit,factor,qty,base_qty,price,price_source,discount_amount,line_amount,tax_rate,outbound_qty) VALUES(1202,101,601,1201,501,1,'PCS',1,4,4,20,'MANUAL',0.0001,79.9999,?::numeric,4)",taxRate);seed("INSERT INTO sal_order_alloc(id,country_id,book_id,order_id,order_line_id,warehouse_id,alloc_qty,outbound_qty) VALUES(1203,101,601,1201,1202,401,4,4)");seed("UPDATE sal_order SET approval_status='APPROVED' WHERE id=1201");seed("INSERT INTO sal_outbound(id,country_id,book_id,order_id,warehouse_id,doc_no,biz_date) VALUES(1204,101,601,1201,401,'OUT','2026-10-15')");seed("INSERT INTO sal_outbound_line(id,country_id,book_id,outbound_id,order_line_id,alloc_id,product_id,qty,price,amount) VALUES(1205,101,601,1204,1202,1203,501,4,20,79.9999)");});inCountry(101,()->inventory.outbound(c(),new InventoryApi.Outbound(601,401,501,null,new BigDecimal("4"),null,new InventoryApi.Source("SAL_OUTBOUND",1204,1205,"OUT"),LocalDate.of(2026,10,15))));long cogs=owner.queryForObject("SELECT id FROM cst_cogs WHERE source_line_id=1205",Long.class);seed("UPDATE sal_outbound_line SET cogs_id=? WHERE id=1205",cogs);seed("INSERT INTO sal_outbound_batch(country_id,outbound_line_id,batch_id,qty) SELECT 101,1205,batch_id,qty FROM cst_cogs_part WHERE cogs_id=? AND part_type='CONSUMED'",cogs);seed("UPDATE sal_outbound SET status='OUTBOUNDED',outbound_at=clock_timestamp() WHERE id=1204");}
 @Test void frozenCostsAndConfirmedExpenseAllocationsProduceContributionWithoutAnyReadWrites(){stock("MXN","10");sale("MXN");seed("INSERT INTO md_expense_item(id,country_id,code,name,cost_treatment) VALUES(804,101,'DIRECT','Direct','DIRECT_SELLING'),(805,101,'PERIOD','Period','PERIOD_EXPENSE')");valuation.createExpense(c(),Map.of("bookId",601,"expenseItemId",804,"currency","MXN","amount",3,"bizDate","2026-10-15","lines",List.of(Map.of("productId",501,"amount",3))),key());valuation.createExpense(c(),Map.of("bookId",601,"expenseItemId",805,"currency","MXN","amount",2,"bizDate","2026-10-15"),key());valuation.createExpense(c(),Map.of("bookId",601,"expenseItemId",805,"currency","MXN","amount",1,"bizDate","2026-10-15","lines",List.of(Map.of("productId",501,"amount",1))),key());var before=owner.queryForMap("SELECT (SELECT count(*) FROM cst_cogs) cogs,(SELECT count(*) FROM cst_valuation_change) changes,(SELECT count(*) FROM cst_expense_record) expenses,(SELECT count(*) FROM cst_cogs_completion) completions");var result=profit("periodId=701");assertThat(owner.queryForMap("SELECT (SELECT count(*) FROM cst_cogs) cogs,(SELECT count(*) FROM cst_valuation_change) changes,(SELECT count(*) FROM cst_expense_record) expenses,(SELECT count(*) FROM cst_cogs_completion) completions")).isEqualTo(before);assertThat(profit("periodId=701").get("sourceHash")).isEqualTo(result.get("sourceHash"));var row=product(result,501);amount(row,"netSalesAmount","80");amount(row,"cogsAmount","40");amount(row,"grossProfit","40");amount(row,"periodExpense","1");amount(row,"contributionProfit","36");amount(product(result,0),"periodExpense","2");assertThat(row.get("completeness")).isEqualTo("ESTIMATED");assertThat(result).containsEntry("fresh",true).containsEntry("baseCurrency","MXN").containsEntry("timezone","America/Mexico_City");assertThat(result.get("disclaimer").toString()).contains("未包含线下营销费用");assertThat(result.get("differences").toString()).contains("未记账业务");assertThat(((Map<?,?>)row.get("originalAmounts")).get("netSalesAmount").toString()).isEqualTo("79.9999");}
 @Test void missingCostOrFrozenSalesFxIsInsufficientAndNeverZero(){stock("CNY","2");sale("MXN");var row=product(profit("periodId=701"),501);assertThat(row).containsEntry("completeness","INSUFFICIENT").containsEntry("cogsAmount",null).containsEntry("grossProfit",null).containsEntry("contributionProfit",null);}
 @Test void foreignSalesWithoutFrozenRateRemainInsufficientEvenIfLiveRateExists(){stock("MXN","10");sale("CNY");seed("INSERT INTO md_exchange_rate(country_id,from_ccy,to_ccy,scope,rate_date,rate,status) VALUES(101,'CNY','MXN','PURCHASE_COST','2026-10-15',3,'CONFIRMED')");var row=product(profit("periodId=701"),501);assertThat(row).containsEntry("completeness","INSUFFICIENT").containsEntry("netSalesAmount",null).containsEntry("grossProfit",null);}
 @Test void currentFieldRevocationMasksNestedCostAndDerivedProfitAndBookScopeIsEnforced(){stock("MXN","10");sale("MXN");profit("periodId=701");seed("UPDATE sys_role SET field_policies='{\"ORDER_TOTAL\":\"READ\",\"PROFIT\":\"READ\"}' WHERE id=202");var row=product(profit("periodId=701"),501);assertThat(row).doesNotContainKeys("cogsAmount","grossProfit","contributionProfit");assertThat(row.get("originalAmounts").toString()).doesNotContain("cogsAmount","grossProfit","contributionProfit");seed("DELETE FROM sys_user_data_scope WHERE user_id=201");assertThat(http("cst/profit?bookId=601&periodId=701",null).get("httpStatus")).isEqualTo(404);}
 @Test void aiUnconfiguredHasNoInventedHistoryAndRejectsAnalysisAfterCurrentPermissionCheck(){var history=http("ai/history",null);assertThat(history.get("httpStatus")).as(history.toString()).isEqualTo(200);assertThat(history.get("data").toString()).contains("records=[]");var r=http("ai/analysis",Map.of("bookId",601,"periodId",701,"question","解释单品利润"));assertThat(r.get("code")).isEqualTo("AI_PROVIDER_NOT_CONFIGURED");seed("UPDATE sys_role SET permissions='[\"cst:profit:view\"]' WHERE id=202");assertThat(http("ai/analysis",Map.of("bookId",601,"periodId",701)).get("httpStatus")).isEqualTo(403);}
 @SuppressWarnings("unchecked") long returnLine(Map<String,Object> r){return ((Number)((Map<String,Object>)((List<?>)r.get("lines")).getFirst()).get("id")).longValue();}
 Map<String,Object> returnedOne(){workflow.createRule(c(),Map.of("docType","SALES_RETURN","name","Return approval","conditions",List.of(),"nodes",List.of(Map.of("nodeName","Finance","approverType","USER","approverRef",201,"mode","ANY"))));var r=returns.createSales(c(),Map.of("orderId",1201,"outboundId",1204,"returnWarehouseId",401,"reasonCode","QUALITY","responsibility","SUPPLIER","bizDate","2026-10-16","submit",true,"lines",List.of(Map.of("outboundLineId",1205,"qty",1))),key());long task=owner.queryForObject("SELECT id FROM wf_task WHERE status='PENDING'",Long.class);workflow.approve(c(),task,"verified return");r=returns.receive(c(),id(r),Map.of("bizDate","2026-10-16","waitForMore",true,"lines",List.of(Map.of("id",returnLine(r),"receivedQty",1))),key());return returns.inspect(c(),id(r),Map.of("bizDate","2026-10-16","lines",List.of(Map.of("id",returnLine(r),"goodQty",1,"frozenQty",0,"freezeType",""))),key());}
 @Test void returnInspectionAndVersionedSettlementUseTheirOwnDatesAndReversalPreservesHistory(){stock("MXN","10");sale("MXN");var r=returnedOne();long ret=id(r);returns.settleSales(c(),ret,Map.of("bizDate","2026-11-01"),key());returns.reverseSales(c(),ret,Map.of("bizDate","2026-11-02","reason","correct settlement"),key());returns.settleSales(c(),ret,Map.of("bizDate","2026-11-03"),key());var oct=product(profit("periodId=701"),501);amount(oct,"netSalesAmount","80");amount(oct,"cogsAmount","30");amount(product(profit("from=2026-11-01&to=2026-11-01"),501),"netSalesAmount","-20");amount(product(profit("from=2026-11-02&to=2026-11-02"),501),"netSalesAmount","20");amount(product(profit("periodId=702"),501),"netSalesAmount","-20");}
 @Test void closedPeriodDoesNotTakeLaterCostCompletionOrRepriceItsFrozenCogs(){long batch=stock("CNY","2");sale("MXN");seed("UPDATE fin_period SET status='CLOSED',closed_at=clock_timestamp() WHERE id=701");seed("INSERT INTO md_exchange_rate(country_id,from_ccy,to_ccy,scope,rate_date,rate,status) VALUES(101,'CNY','MXN','PURCHASE_COST','2026-10-15',3,'CONFIRMED')");long cost=owner.queryForObject("SELECT id FROM cst_inbound_cost WHERE batch_id=?",Long.class,batch);valuation.confirm(c(),cost,Map.of("bizDate","2026-11-01"),key());var row=product(profit("periodId=701"),501);assertThat(row).containsEntry("completeness","INSUFFICIENT").containsEntry("cogsAmount",null);assertThat(owner.queryForObject("SELECT amount FROM cst_cogs_completion",BigDecimal.class)).isEqualByComparingTo("24");}
 @Test void bookCurrencyAndCountryTimezoneAreReadFromCurrentBookInsteadOfAssumedMexico(){seed("UPDATE fin_book SET base_currency='CNY' WHERE id=601");seed("UPDATE sys_country SET code='CN',default_currency='CNY',timezone='Asia/Shanghai' WHERE id=101");stock("CNY","1.2345");sale("CNY");var result=profit("periodId=701");assertThat(result).containsEntry("baseCurrency","CNY").containsEntry("countryCode","CN").containsEntry("timezone","Asia/Shanghai");amount(product(result,501),"cogsAmount","4.94");assertThat(((Map<?,?>)product(result,501).get("originalAmounts")).get("cogsAmount").toString()).isEqualTo("4.9380");}

 @Test void capitalizedLateFeeAddsOnlySoldDifferenceAndPairedReturnCostIsNotCountedTwice(){var delivery=delivery();var received=receipt(delivery);lgs.action(c(),"receipts",id(received),"confirm",Map.of(),key());seed("INSERT INTO md_exchange_rate(country_id,from_ccy,to_ccy,scope,rate_date,rate,status) VALUES(101,'CNY','MXN','PURCHASE_COST','2026-10-15',1,'CONFIRMED')");long cost=owner.queryForObject("SELECT id FROM cst_inbound_cost",Long.class);valuation.confirm(c(),cost,Map.of(),key());sale("MXN");var original=owner.queryForMap("SELECT * FROM cst_cogs WHERE source_type='SAL_OUTBOUND'");var fee=lgs.create(c(),"fees",Map.of("refType","SHIPMENT","refId",delivery.get("shipmentId"),"carrierId",802,"expenseItemId",803,"currency","MXN","amount",90,"estimateFlag","ESTIMATE","bizDate","2026-10-15","confirm",true),key());var allocation=valuation.createAllocation(c(),Map.of("feeId",id(fee),"basis","QTY","bizDate","2026-10-15"),key());valuation.allocationAction(c(),id(allocation),"confirm",Map.of("bizDate","2026-10-16"),key());amount(product(profit("periodId=701"),501),"cogsAmount","60");assertThat(product(profit("from=2026-10-16&to=2026-10-16"),501).get("completeness")).isEqualTo("ESTIMATED");returnedOne();var row=product(profit("periodId=701"),501);amount(row,"cogsAmount","45");amount(row,"periodExpense","0");assertThat(owner.queryForMap("SELECT * FROM cst_cogs WHERE source_type='SAL_OUTBOUND'")).isEqualTo(original);assertThat(owner.queryForObject("SELECT count(*) FROM cst_cost_adjustment WHERE source_type='RETURN_COST'",Integer.class)).isEqualTo(2);}
 @Test void nonzeroTaxWithoutConfirmedNetTaxFactIsInsufficientAndRetainsOriginalSaleAmount(){stock("MXN","10");sale("MXN","0.16");var row=product(profit("periodId=701"),501);assertThat(row).containsEntry("netSalesAmount",null).containsEntry("completeness","INSUFFICIENT");amount(row,"cogsAmount","40");assertThat(row.get("sources").toString()).contains("originalSalesAmount=79.9999","taxBasisMissing=true");}

 @Test void returnRevenueCarriesTheOriginalTaxCompletenessAcrossPeriods(){stock("MXN","10");sale("MXN","0.16");var r=returnedOne();returns.settleSales(c(),id(r),Map.of("bizDate","2026-11-01"),key());var row=product(profit("periodId=702"),501);assertThat(row).containsEntry("netSalesAmount",null).containsEntry("completeness","INSUFFICIENT");}

 @Test void profitOnlyRoleCanSelectItsAuthorizedBookWithoutFinancialOperationPermission(){seed("UPDATE sys_role SET permissions='[\"cst:profit:view\"]' WHERE id=202");assertThat(http("fin/books",null).get("httpStatus")).isEqualTo(200);assertThat(http("fin/periods",Map.of("bookId",601,"fiscalYear",2026)).get("httpStatus")).isEqualTo(403);}

}
